static lstr L9040 = {-1, 2913, "// std/async: the functions of task handles (SPEC.md section 8, D109).\012//\012// An Async<T> is the handle of a task; the type is builtin and needs no\012// import. The handle functions go through the primitives of\012// std/internal/async; all and race are async blocks, which the stage 1\012// compiler builds (the committed seed never compiles this module).\012\012import * as Arrays from \"std/array\"\012import * as Ranges from \"std/range\"\012import * as Tasks from \"std/internal/async\"\012\012// The error of every suspending std function.\012export enum AsyncError {\012  Cancelled\012  Failed(message: string)\012}\012\012// Lets the task run with nobody waiting. The task keeps running to its end, or\012// until the program exits.\012export function detach<T>(_handle: Async<T>) {}\012\012// A handle that finishes once no other task of the loop can run: none is\012// ready, sleeping or waiting on I/O, counting tasks started while it waits.\012// Idle handles finish one at a time, oldest first. In a cancelled task it\012// finishes at once.\012export function idle(): Async<void> uses alloc {\012  return Tasks.idle()\012}\012\012// Runs callback with the value when the task finishes, or on the next loop\012// turn if it has. A cancelled task drops the callback without running it. For\012// an Async<void> the callback takes no argument.\012export function then<T, effect E>(\012  handle: Async<T>,\012  escaping callback: (value: T) => void uses E\012) uses E, alloc {\012  // The runtime calls this only for a task that finished without a cancel.\012  Tasks.then(handle, (finished: Async<T>) => callback(Tasks.value(finished)))\012}\012\012// The value once the task has finished; None before that and after a cancel.\012export function peek<T>(handle: Async<T>): Option<T> uses alloc {\012  if (Tasks.finished(handle)) {\012    return Some(Tasks.value(handle))\012  }\012  return None\012}\012\012// Cancels the task: its then callbacks are dropped, peek gives None, a sleep\012// or Async.idle it waits in ends at once, and its suspending std calls give\012// Err(AsyncError.Cancelled). A finished task is left as it is.\012export function cancel<T>(handle: Async<T>) {\012  Tasks.cancel(handle)\012}\012\012// Every value, in the order of the handles, once each task has finished.\012export function all<T>(handles: Array<Async<T>>): Async<Array<T>> from handles uses alloc {\012  return async {\012    let values: Array<T> = []\012    for (const handle of Arrays.values(handles)) {\012      Arrays.push(mutable values, await handle)\012    }\012    return values\012  }\012}\012\012// The value of the first task to finish, or None for no handles. The other\012// tasks keep running.\012export function race<T>(handles: Array<Async<T>>): Async<Option<T>> from handles uses alloc {\012  return async {\012    if (Arrays.length(handles) == 0) {\012      return None\012    }\012    const winner = Tasks.winner()\012    for (const index of Ranges.between(0, Arrays.length(handles))) {\012      Tasks.watch(winner, handles[index], index)\012    }\012    const first = await winner\012    return Some(await handles[first])\012  }\012}\012"};
static lstr L9041 = {-1, 14, "std/async/file"};
static lstr L9042 = {-1, 2626, "// std/async/file: whole-file reads and writes for async code (SPEC.md section 8, D109).\012//\012// kqueue and epoll do not wait on regular files, so each call reads or writes\012// in one blocking step, as std/fs does, then lets the other ready tasks run\012// once before it returns. A cancelled task's call gives\012// Err(AsyncError.Cancelled) before it touches the file.\012\012import * as Fs from \"std/fs\"\012import * as Tasks from \"std/internal/async\"\012import * as Handles from \"std/internal/asyncio\"\012import { AsyncError } from \"std/async\"\012\012// The text of the file at path.\012export async function readText(path: string): Result<string, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.readText(path)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(text) => Ok(text), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// The bytes of the file at path.\012export async function readBytes(path: string): Result<bytes, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.readBytes(path)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(data) => Ok(data), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// Writes text to the file at path, replacing it, and gives the bytes written.\012export async function writeText(\012  path: string,\012  text: string,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.writeText(path, text)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(count) => Ok(count), Err(message) => Err(AsyncError.Failed(message)) }\012}\012\012// Writes data to the file at path, replacing it, and gives the bytes written.\012export async function writeBytes(\012  path: string,\012  data: bytes,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const result = Fs.writeBytes(path, data)\012  // A zero timer fires after the ready tasks: one turn for them. The work is\012  // done, so a cancel now changes nothing.\012  const _turn = await Tasks.sleep(0)\012  return match (result) { Ok(count) => Ok(count), Err(message) => Err(AsyncError.Failed(message)) }\012}\012"};
static lstr L9043 = {-1, 13, "std/async/net"};
static lstr L9044 = {-1, 5216, "// std/async/net: TCP sockets on the loop of the thread (SPEC.md section 8, D109).\012//\012// listen and localPort do not suspend. accept, connect, read and write wait in\012// the loop until the socket is ready, so the other tasks run meanwhile. A\012// Listener or a Connection is a handle: copies share the socket, and it\012// closes when the last copy is dropped. host is a numeric IPv4 or IPv6\012// address; there is no name lookup.\012\012import * as Bytes from \"std/bytes\"\012import * as Handles from \"std/internal/asyncio\"\012import { AsyncError } from \"std/async\"\012\012export opaque struct Listener {\012  handle: Handle\012}\012\012export opaque struct Connection {\012  handle: Handle\012}\012\012function failWith(code: int): AsyncError uses alloc {\012  return AsyncError.Failed(Handles.message(code))\012}\012\012// The error of a wait that ended with ready: None when the socket is ready.\012// Each suspending function waits itself, never through a helper task, so a\012// cancel of the task that awaits it reaches the wait. One task at a time may\012// wait in each direction; busy names what the other task already does.\012function checkWait(ready: int, busy: string): Option<AsyncError> uses alloc {\012  if (ready < 0) {\012    return Some(AsyncError.Cancelled)\012  }\012  if (Handles.busy(ready)) {\012    return Some(AsyncError.Failed(`another task is already ${busy}`))\012  }\012  if (ready > 0) {\012    return Some(failWith(ready))\012  }\012  return None\012}\012\012// A socket that accepts connections on host and port. Port 0 picks a free\012// port, which localPort gives.\012export function listen(host: string, port: int): Result<Listener, AsyncError> uses io, alloc {\012  const handle = Handles.listen(host, port)\012  const code = Handles.error()\012  if (code != 0) {\012    return Err(failWith(code))\012  }\012  return Ok(Listener { handle: handle })\012}\012\012// The port the listener is bound to.\012export function localPort(listener: Listener): int uses io {\012  return Handles.localPort(listener.handle)\012}\012\012// The next connection to the listener.\012export async function accept(listener: Listener): Result<Connection, AsyncError> uses io, alloc {\012  while (true) {\012    if (Handles.cancelled()) {\012      return Err(AsyncError.Cancelled)\012    }\012    const handle = Handles.accept(listener.handle)\012    const code = Handles.error()\012    if (code == 0) {\012      return Ok(Connection { handle: handle })\012    }\012    // A connection that went before it was taken leaves the others to accept.\012    if (!Handles.acceptAgain(code)) {\012      if (!Handles.retry(code)) {\012        return Err(failWith(code))\012      }\012      const problem = checkWait(\012        await Handles.wait(listener.handle, false),\012        \"accepting on this listener\",\012      )\012      if (problem is Some(error)) {\012        return Err(error)\012      }\012    }\012  }\012  return Err(AsyncError.Cancelled)\012}\012\012// A connection to host and port.\012export async function connect(\012  host: string,\012  port: int,\012): Result<Connection, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  const handle = Handles.connect(host, port)\012  const code = Handles.error()\012  if (code == 0) {\012    return Ok(Connection { handle: handle })\012  }\012  if (!Handles.pending(code)) {\012    return Err(failWith(code))\012  }\012  const problem = checkWait(await Handles.wait(handle, true), \"connecting this socket\")\012  if (problem is Some(error)) {\012    return Err(error)\012  }\012  const result = Handles.connected(handle)\012  if (result != 0) {\012    return Err(failWith(result))\012  }\012  return Ok(Connection { handle: handle })\012}\012\012// Up to maxBytes bytes from the connection, at most 64 KiB, once some are\012// there. Empty bytes mean the peer has closed its side; a maxBytes of zero or\012// less gives empty bytes at once.\012export async function read(\012  connection: Connection,\012  maxBytes: int,\012): Result<bytes, AsyncError> uses io, alloc {\012  while (true) {\012    if (Handles.cancelled()) {\012      return Err(AsyncError.Cancelled)\012    }\012    const data = Handles.read(connection.handle, maxBytes)\012    const code = Handles.error()\012    if (code == 0) {\012      return Ok(data)\012    }\012    if (!Handles.retry(code)) {\012      return Err(failWith(code))\012    }\012    const problem = checkWait(\012      await Handles.wait(connection.handle, false),\012      \"reading this connection\",\012    )\012    if (problem is Some(error)) {\012      return Err(error)\012    }\012  }\012  return Err(AsyncError.Cancelled)\012}\012\012// Writes every byte of data and gives the count. A cancel while it waits\012// ends it with Err(AsyncError.Cancelled), whatever part was sent.\012export async function write(\012  connection: Connection,\012  data: bytes,\012): Result<int, AsyncError> uses io, alloc {\012  if (Handles.cancelled()) {\012    return Err(AsyncError.Cancelled)\012  }\012  let sent = 0\012  const total = Bytes.length(data)\012  // A wait that a cancel ends gives -1, so the loop needs no second check.\012  while (sent < total) {\012    const count = Handles.write(connection.handle, data, sent)\012    const code = Handles.error()\012    if (code == 0) {\012      sent += count\012    } else if (!Handles.retry(code)) {\012      return Err(failWith(code))\012    } else {\012      const problem = checkWait(\012        await Handles.wait(connection.handle, true),\012        \"writing this connection\",\012      )\012      if (problem is Some(error)) {\012        return Err(error)\012      }\012    }\012  }\012  return Ok(sent)\012}\012"};
static lstr L9045 = {-1, 14, "std/async/time"};
static lstr L9046 = {-1, 787, "// std/async/time: sleep on the loop of the thread (SPEC.md section 8, D109).\012//\012// sleep suspends the running task until the duration has passed; the other\012// tasks of the loop run meanwhile. Time.sleep of std/time blocks the loop.\012\012import * as Tasks from \"std/internal/async\"\012import * as Time from \"std/time\"\012import { Duration } from \"std/time\"\012import { AsyncError } from \"std/async\"\012\012// Waits for duration and gives the time slept, or Err(AsyncError.Cancelled)\012// at once when the task is cancelled, before or while it waits.\012export async function sleep(duration: Duration): Result<Duration, AsyncError> uses io, alloc {\012  const slept = await Tasks.sleep(Time.asNanoseconds(duration))\012  if (slept < 0) {\012    return Err(AsyncError.Cancelled)\012  }\012  return Ok(Time.nanoseconds(slept))\012}\012"};
static lstr L9047 = {-1, 9, "std/build"};
static lstr L9048 = {-1, 1133, "// std/build: the target a program is built for. The compiler sets os, arch and\012// debug for each build; the values written here are replaced. An `if` that\012// tests only these constants keeps one branch in the output.\012\012import * as Host from \"std/internal/host\"\012\012export enum Os derives Show, Equatable {\012  MacOS\012  Linux\012  Windows\012}\012\012export enum Arch derives Show, Equatable {\012  Arm64\012  X86_64\012}\012\012export const os: Os = Os.Linux\012export const arch: Arch = Arch.X86_64\012export const debug: bool = true\012\012export struct Target {\012  os: Os\012  arch: Arch\012}\012\012export function hostTarget(): Option<Target> {\012  const hostOs = Host.os()\012  const hostArch = Host.arch()\012  // The C compiler's predefined macros give the codes; 0 is a machine with no variant here.\012  if (hostOs == 0 || hostArch == 0) {\012    return None\012  }\012  if (hostOs == 1 && hostArch == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.Arm64 })\012  }\012  if (hostOs == 1) {\012    return Some(Target { os: Os.MacOS, arch: Arch.X86_64 })\012  }\012  if (hostArch == 1) {\012    return Some(Target { os: Os.Linux, arch: Arch.Arm64 })\012  }\012  return Some(Target { os: Os.Linux, arch: Arch.X86_64 })\012}\012"};
static lstr L9049 = {-1, 8, "std/cell"};
static lstr L9050 = {-1, 870, "// std/cell: Cell<T>, one mutable slot that every copy of the handle shares.\012//\012// A Cell is an identity type: copying it, capturing it in a closure or storing it in a\012// struct copies the handle, and Cell.set through any copy changes what all of them read.\012\012import * as Boxes from \"std/box\"\012import * as Slot from \"std/internal/cell\"\012\012export opaque struct Cell<T> {\012  slot: Box<T>\012}\012\012export function create<T>(value: T): Cell<T> uses alloc {\012  return Cell { slot: Boxes.new(value) }\012}\012\012export function get<T>(cell: Cell<T>): T from cell {\012  return cell.slot.value\012}\012\012export function set<T>(cell: Cell<T>, value: T) {\012  Slot.store(cell.slot, value)\012}\012\012export function update<T, effect E>(cell: Cell<T>, change: (value: T) => T uses E) uses E {\012  // Hold the old value, so a set inside change cannot free it.\012  const old = get(cell)\012  Slot.store(cell.slot, change(old))\012}\012"};
static lstr L9051 = {-1, 13, "std/coroutine"};
static lstr L9052 = {-1, 1043, "// std/coroutine: Co.resume runs a generator or a coroutine to its next yield.\012//\012// The compiler turns `Co.resume(mutable g)` into resumeGenerator and\012// `Co.resume(mutable g, input)` into resumeCoroutine, by argument count.\012\012import * as Internal from \"std/internal/coroutine\"\012\012export enum Step<Out> derives Show, Equatable {\012  Yielded(value: Out)\012  Done\012  Panicked(message: string)\012}\012\012export function resumeGenerator<T, effect E>(\012  mutable g: Generator<T> uses E\012): Step<T> uses E, alloc {\012  return readStep(Internal.next(mutable g))\012}\012\012export function resumeCoroutine<In, Out, effect E>(\012  mutable g: Coroutine<In, Out> uses E,\012  input: In,\012): Step<Out> uses E, alloc {\012  return readStep(Internal.resume(mutable g, input))\012}\012\012// readStep reads the outcome of one resume: a value, the end, or a panic.\012function readStep<T>(next: Option<T>): Step<T> from next uses alloc {\012  if (next is Some(value)) {\012    return Step.Yielded(value)\012  }\012  if (Internal.panicked()) {\012    return Step.Panicked(Internal.panicMessage())\012  }\012  return Step.Done\012}\012"};
static lstr L9053 = {-1, 11, "std/cstring"};
static lstr L9054 = {-1, 1182, "// std/cstring: CString, a string with no zero byte, which C reads as a zero-terminated string.\012//\012// Pass `CStrings.pointer(text)` to a C function that takes `char*`; the pointer is valid while\012// the CString is. `CStrings.read` copies a zero-terminated string that C returns.\012\012import * as Bytes from \"std/bytes\"\012import * as Str from \"std/string\"\012import * as Ptr from \"std/ptr\"\012import * as Text from \"std/internal/cstring\"\012\012export opaque struct CString {\012  text: string\012}\012\012export function from(text: string): Option<CString> {\012  // C would stop at a zero byte, so a string that holds one has no CString.\012  const length = Str.length(text)\012  for (let index = 0; index < length; index++) {\012    if (Str.byteAt(text, index) == 0) {\012      return None\012    }\012  }\012  return Some(CString { text: text })\012}\012\012export function toString(value: CString): string from value {\012  return value.text\012}\012\012export function pointer(value: CString): Ptr<u8> {\012  return Text.pointer(value.text)\012}\012\012export function read(address: Ptr<u8>): Result<string, string> uses alloc, unsafe {\012  let copied: Result<string, string> = Err(\"\")\012  unsafe {\012    copied = Bytes.toString(Text.read(address))\012  }\012  return copied\012}\012"};
