static lstr L9056 = {-1, 833, "// std/array: helpers over Array. The functions that need the compiler are built in.\012\012import * as Arrays from \"std/array\"\012\012export function map<T, U, effect E>(\012  items: Array<T>,\012  change: (value: T) => U uses E\012): Array<U> uses alloc, E {\012  let result: Array<U> = Arrays.withCapacity(Arrays.length(items))\012  for (const item of items) {\012    Arrays.push(mutable result, change(item))\012  }\012  return result\012}\012\012export function slice<T>(items: Array<T>, start: int, finish: int): Option<Array<T>> uses alloc {\012  // A range outside the array has no slice.\012  if (start < 0 || finish > Arrays.length(items) || start > finish) {\012    return None\012  }\012  let result: Array<T> = Arrays.withCapacity(finish - start)\012  for (let index = start; index < finish; index++) {\012    Arrays.push(mutable result, copy(items[index]))\012  }\012  return Some(result)\012}\012"};
