static lstr L9064 = {-1, 425, "// std/fixedarray: helpers over FixedArray. An index written as values[i] must be\012// proven in range; get checks the index and returns None outside it.\012\012export function get<T, const N: int>(values: FixedArray<T, N>, index: int): Option<T> from values {\012  if (index >= 0 && index < N) {\012    return Some(values[index])\012  }\012  return None\012}\012\012export function length<T, const N: int>(_values: FixedArray<T, N>): int {\012  return N\012}\012"};
static lstr L9065 = {-1, 8, "std/hash"};
static lstr L9066 = {-1, 670, "// std/hash: hashing. `of` is the hash of a Hashable value and may change between builds.\012// `fnv1a` is FNV-1a 64 over the UTF-8 bytes of a string and never changes.\012\012import * as Str from \"std/string\"\012import * as U64 from \"std/u64\"\012import * as Ranges from \"std/range\"\012\012const FNV_OFFSET: u64 = 14695981039346656037\012const FNV_PRIME: u64 = 1099511628211\012\012export function of<T: Hashable>(value: T): int {\012  return Hashable.hash(value)\012}\012\012export function fnv1a(text: string): u64 {\012  let state = FNV_OFFSET\012  const length = Str.length(text)\012  for (const index of Ranges.upTo(length)) {\012    state = (state ^ U64.wrap(Str.byteAt(text, index))) * FNV_PRIME\012  }\012  return state\012}\012"};
static lstr L9067 = {-1, 8, "std/json"};
static lstr L9068 = {-1, 16470, "// std/json: parse and stringify JSON text (RFC 8259) as a Value of std/shape.\012\012import * as Str from \"std/string\"\012import * as Int from \"std/int\"\012import * as Char from \"std/char\"\012import * as Float from \"std/float\"\012import * as Arrays from \"std/array\"\012import * as Maps from \"std/map\"\012import * as FloatText from \"std/internal/float\"\012import { Value, Shape } from \"std/shape\"\012\012// Containers nested deeper than this are an error, so the recursion is bounded.\012const MAX_DEPTH = 512\012\012struct Parser {\012  text: string\012  length: int\012  position: int\012}\012\012// parse reads one JSON value. Errors read `<line>:<column>: <reason>`.\012export function parse(text: string): Result<Value, string> uses alloc {\012  let parser = Parser { text: text, length: Str.length(text), position: 0 }\012  skipSpace(mutable parser)\012  const value = parseValue(mutable parser, 0)\012  if (value is Err(message)) {\012    return Err(message)\012  }\012  skipSpace(mutable parser)\012  if (parser.position < parser.length) {\012    return fail(parser, parser.position, \"unexpected character after the value\")\012  }\012  return Ok(value.value)\012}\012\012// stringify writes a value as compact JSON text. A non-finite Float is null.\012export function stringify(value: Value): string uses alloc {\012  let builder = Str.builder()\012  writeValue(mutable builder, value)\012  return Str.build(builder)\012}\012\012// fail builds the error for the byte at position, as line:column: reason.\012function fail<T>(parser: Parser, position: int, reason: string): Result<T, string> uses alloc {\012  let line = 1\012  let column = 1\012  let index = 0\012  while (index < position && index < parser.length) {\012    const byte = Str.byteAt(parser.text, index)\012    if (byte == 10) {\012      line += 1\012      column = 1\012    } else if (byte < 128 || byte >= 192) {\012      column += 1\012    }\012    index += 1\012  }\012  if (position >= parser.length) {\012    return Err(`${Int.toString(line)}:${Int.toString(column)}: unexpected end of input`)\012  }\012  return Err(`${Int.toString(line)}:${Int.toString(column)}: ${reason}`)\012}\012\012function cutText(text: string, start: int, end: int): string uses alloc {\012  if (Str.slice(text, start, end) is Some(piece)) {\012    return piece\012  }\012  panic(\"cutText: the range is outside the text\")\012}\012\012function skipSpace(mutable parser: Parser) {\012  while (parser.position < parser.length) {\012    const byte = Str.byteAt(parser.text, parser.position)\012    if (byte != 32 && byte != 9 && byte != 10 && byte != 13) {\012      return\012    }\012    parser.position += 1\012  }\012}\012\012function parseValue(mutable parser: Parser, depth: int): Result<Value, string> uses alloc {\012  if (parser.position >= parser.length) {\012    return fail(parser, parser.position, \"expected a value\")\012  }\012  const byte = Str.byteAt(parser.text, parser.position)\012  if (byte == 123) {\012    return parseRecord(mutable parser, depth + 1)\012  }\012  if (byte == 91) {\012    return parseList(mutable parser, depth + 1)\012  }\012  if (byte == 34) {\012    const text = parseString(mutable parser)\012    if (text is Err(message)) {\012      return Err(message)\012    }\012    return Ok(Value.Text(text.value))\012  }\012  if (byte == 45 || (byte >= 48 && byte <= 57)) {\012    return parseNumber(mutable parser)\012  }\012  if (readWord(mutable parser, \"true\")) {\012    return Ok(Value.Bool(true))\012  }\012  if (readWord(mutable parser, \"false\")) {\012    return Ok(Value.Bool(false))\012  }\012  if (readWord(mutable parser, \"null\")) {\012    return Ok(Value.Null)\012  }\012  return fail(parser, parser.position, \"expected a value\")\012}\012\012// readWord consumes word when the text continues with it. It compares bytes,\012// because a slice of the text could end inside a multibyte character.\012function readWord(mutable parser: Parser, word: string): bool {\012  const count = Str.length(word)\012  if (parser.position + count > parser.length) {\012    return false\012  }\012  let index = 0\012  while (index < count) {\012    if (Str.byteAt(parser.text, parser.position + index) != Str.byteAt(word, index)) {\012      return false\012    }\012    index += 1\012  }\012  parser.position += count\012  return true\012}\012\012function parseList(mutable parser: Parser, depth: int): Result<Value, string> uses alloc {\012  if (depth > MAX_DEPTH) {\012    return fail(parser, parser.position, \"nesting is deeper than 512\")\012  }\012  // Skip the [.\012  parser.position += 1\012  let items: Array<Value> = []\012  skipSpace(mutable parser)\012  if (parser.position < parser.length && Str.byteAt(parser.text, parser.position) == 93) {\012    parser.position += 1\012    return Ok(Value.List(items))\012  }\012  while (true) {\012    skipSpace(mutable parser)\012    const item = parseValue(mutable parser, depth)\012    if (item is Err(message)) {\012      return Err(message)\012    }\012    Arrays.push(mutable items, item.value)\012    skipSpace(mutable parser)\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"expected , or ]\")\012    }\012    const byte = Str.byteAt(parser.text, parser.position)\012    parser.position += 1\012    if (byte == 93) {\012      return Ok(Value.List(items))\012    }\012    if (byte != 44) {\012      return fail(parser, parser.position - 1, \"expected , or ]\")\012    }\012  }\012  return fail(parser, parser.position, \"unreachable\")\012}\012\012function parseRecord(mutable parser: Parser, depth: int): Result<Value, string> uses alloc {\012  if (depth > MAX_DEPTH) {\012    return fail(parser, parser.position, \"nesting is deeper than 512\")\012  }\012  // Skip the {.\012  parser.position += 1\012  let fields: Map<string, Value> = Map {}\012  skipSpace(mutable parser)\012  if (parser.position < parser.length && Str.byteAt(parser.text, parser.position) == 125) {\012    parser.position += 1\012    return Ok(Value.Record(fields))\012  }\012  while (true) {\012    skipSpace(mutable parser)\012    if (parser.position >= parser.length || Str.byteAt(parser.text, parser.position) != 34) {\012      return fail(parser, parser.position, \"expected a string key\")\012    }\012    const key = parseString(mutable parser)\012    if (key is Err(message)) {\012      return Err(message)\012    }\012    skipSpace(mutable parser)\012    if (parser.position >= parser.length || Str.byteAt(parser.text, parser.position) != 58) {\012      return fail(parser, parser.position, \"expected :\")\012    }\012    parser.position += 1\012    skipSpace(mutable parser)\012    const field = parseValue(mutable parser, depth)\012    if (field is Err(message)) {\012      return Err(message)\012    }\012    // The last duplicate wins; an existing key keeps its place.\012    fields[key.value] = field.value\012    skipSpace(mutable parser)\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"expected , or }\")\012    }\012    const byte = Str.byteAt(parser.text, parser.position)\012    parser.position += 1\012    if (byte == 125) {\012      return Ok(Value.Record(fields))\012    }\012    if (byte != 44) {\012      return fail(parser, parser.position - 1, \"expected , or }\")\012    }\012  }\012  return fail(parser, parser.position, \"unreachable\")\012}\012\012function isDigit(byte: int): bool {\012  return byte >= 48 && byte <= 57\012}\012\012// skipDigits moves past a run of digits and says how many there were.\012function skipDigits(mutable parser: Parser): int {\012  let count = 0\012  while (parser.position < parser.length && isDigit(Str.byteAt(parser.text, parser.position))) {\012    parser.position += 1\012    count += 1\012  }\012  return count\012}\012\012function parseNumber(mutable parser: Parser): Result<Value, string> uses alloc {\012  const start = parser.position\012  let isFloat = false\012  if (Str.byteAt(parser.text, parser.position) == 45) {\012    parser.position += 1\012  }\012  // Integer part: 0, or a nonzero digit and more digits.\012  if (parser.position < parser.length && Str.byteAt(parser.text, parser.position) == 48) {\012    parser.position += 1\012  } else if (skipDigits(mutable parser) == 0) {\012    return fail(parser, parser.position, \"invalid number\")\012  }\012  if (parser.position < parser.length && Str.byteAt(parser.text, parser.position) == 46) {\012    isFloat = true\012    parser.position += 1\012    if (skipDigits(mutable parser) == 0) {\012      return fail(parser, parser.position, \"invalid number\")\012    }\012  }\012  if (parser.position < parser.length) {\012    const marker = Str.byteAt(parser.text, parser.position)\012    if (marker == 101 || marker == 69) {\012      isFloat = true\012      parser.position += 1\012      if (parser.position < parser.length) {\012        const sign = Str.byteAt(parser.text, parser.position)\012        if (sign == 43 || sign == 45) {\012          parser.position += 1\012        }\012      }\012      if (skipDigits(mutable parser) == 0) {\012        return fail(parser, parser.position, \"invalid number\")\012      }\012    }\012  }\012  const digits = cutText(parser.text, start, parser.position)\012  if (!isFloat) {\012    // An integer outside int becomes a Float.\012    const whole = Int.parse(digits, 10)\012    if (whole is Ok(number)) {\012      return Ok(Value.Int(number))\012    }\012  }\012  return Ok(Value.Float(FloatText.parse(digits)))\012}\012\012// The value of a hexadecimal digit, or -1.\012function hexValue(byte: int): int {\012  if (byte >= 48 && byte <= 57) {\012    return byte - 48\012  }\012  if (byte >= 97 && byte <= 102) {\012    return byte - 87\012  }\012  if (byte >= 65 && byte <= 70) {\012    return byte - 55\012  }\012  return -1\012}\012\012// readHex4 reads the four hex digits at parser.position.\012function readHex4(mutable parser: Parser): Result<int, string> uses alloc {\012  let code = 0\012  let count = 0\012  while (count < 4) {\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"\")\012    }\012    const digit = hexValue(Str.byteAt(parser.text, parser.position))\012    if (digit < 0) {\012      return fail(parser, parser.position, \"invalid \\\\u escape\")\012    }\012    code = code * 16 + digit\012    parser.position += 1\012    count += 1\012  }\012  return Ok(code)\012}\012\012// parseString reads a string whose opening quote is at parser.position.\012function parseString(mutable parser: Parser): Result<string, string> uses alloc {\012  parser.position += 1\012  let builder = Str.builder()\012  // The start of the plain bytes not yet copied.\012  let runStart = parser.position\012  while (true) {\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"\")\012    }\012    const byte = Str.byteAt(parser.text, parser.position)\012    if (byte == 34) {\012      Str.append(mutable builder, cutText(parser.text, runStart, parser.position))\012      parser.position += 1\012      return Ok(Str.build(builder))\012    }\012    if (byte < 32) {\012      return fail(parser, parser.position, \"control character in string\")\012    }\012    if (byte != 92) {\012      parser.position += 1\012      continue\012    }\012    Str.append(mutable builder, cutText(parser.text, runStart, parser.position))\012    parser.position += 1\012    if (parser.position >= parser.length) {\012      return fail(parser, parser.position, \"\")\012    }\012    const escape = Str.byteAt(parser.text, parser.position)\012    const escapeAt = parser.position - 1\012    parser.position += 1\012    if (escape == 117) {\012      const unit = readHex4(mutable parser)\012      if (unit is Err(message)) {\012        return Err(message)\012      }\012      const code = readCodePoint(mutable parser, unit.value, escapeAt)\012      if (code is Err(message)) {\012        return Err(message)\012      }\012      if (Char.fromCode(code.value) is Some(character)) {\012        Str.appendChar(mutable builder, character)\012      }\012    } else {\012      const simple = simpleEscape(escape)\012      if (simple == \"\") {\012        return fail(parser, escapeAt, \"invalid escape\")\012      }\012      Str.append(mutable builder, simple)\012    }\012    runStart = parser.position\012  }\012  return fail(parser, parser.position, \"unreachable\")\012}\012\012// The text for the escape letter after a backslash, or \"\".\012function simpleEscape(letter: int): string uses alloc {\012  if (letter == 34) {\012    return \"\\\"\"\012  }\012  if (letter == 92) {\012    return \"\\\\\"\012  }\012  if (letter == 47) {\012    return \"/\"\012  }\012  if (letter == 98) {\012    return controlText(8)\012  }\012  if (letter == 102) {\012    return controlText(12)\012  }\012  if (letter == 110) {\012    return \"\\n\"\012  }\012  if (letter == 114) {\012    return \"\\r\"\012  }\012  if (letter == 116) {\012    return \"\\t\"\012  }\012  return \"\"\012}\012\012function controlText(code: int): string uses alloc {\012  if (Char.fromCode(code) is Some(character)) {\012    return Str.fromChar(character)\012  }\012  return \"\"\012}\012\012// readCodePoint joins a surrogate pair; a lone surrogate is an error at escapeAt.\012function readCodePoint(\012  mutable parser: Parser,\012  unit: int,\012  escapeAt: int,\012): Result<int, string> uses alloc {\012  if (unit >= 56320 && unit <= 57343) {\012    return fail(parser, escapeAt, \"lone surrogate\")\012  }\012  if (unit < 55296 || unit > 56319) {\012    return Ok(unit)\012  }\012  // A high surrogate needs \\u and a low surrogate right after it.\012  if (!readWord(mutable parser, \"\\\\u\")) {\012    return fail(parser, escapeAt, \"lone surrogate\")\012  }\012  const low = readHex4(mutable parser)\012  if (low is Err(message)) {\012    return Err(message)\012  }\012  if (low.value < 56320 || low.value > 57343) {\012    return fail(parser, escapeAt, \"lone surrogate\")\012  }\012  return Ok(65536 + (unit - 55296) * 1024 + (low.value - 56320))\012}\012\012function writeValue(mutable builder: StringBuilder, value: Value) uses alloc {\012  match (value) {\012    Value.Null => Str.append(mutable builder, \"null\")\012    Value.Bool(flag) => {\012      if (flag) {\012        Str.append(mutable builder, \"true\")\012      } else {\012        Str.append(mutable builder, \"false\")\012      }\012    }\012    Value.Int(number) => Str.append(mutable builder, Int.toString(number))\012    Value.Float(number) => {\012      // NaN and infinities have no JSON form; JSON.stringify writes null.\012      if (number - number != 0.0) {\012        Str.append(mutable builder, \"null\")\012      } else {\012        Str.append(mutable builder, floatText(number))\012      }\012    }\012    Value.Text(text) => writeString(mutable builder, text)\012    Value.List(items) => {\012      Str.append(mutable builder, \"[\")\012      let first = true\012      for (const item of Arrays.values(items)) {\012        if (!first) {\012          Str.append(mutable builder, \",\")\012        }\012        first = false\012        writeValue(mutable builder, item)\012      }\012      Str.append(mutable builder, \"]\")\012    }\012    Value.Record(fields) => {\012      Str.append(mutable builder, \"{\")\012      let first = true\012      for (const entry of Maps.entries(fields)) {\012        const #[key, field] = entry\012        if (!first) {\012          Str.append(mutable builder, \",\")\012        }\012        first = false\012        writeString(mutable builder, key)\012        Str.append(mutable builder, \":\")\012        writeValue(mutable builder, field)\012      }\012      Str.append(mutable builder, \"}\")\012    }\012  }\012}\012\012// floatText writes a finite Float. A whole number below 1e15 reads as digits and\012// \".0\" (Float.toString would write 1e+02 for 100.0); the rest keeps its shortest text.\012function floatText(number: f64): string uses alloc {\012  if (number > -1000000000000000.0 && number < 1000000000000000.0) {\012    if (Float.truncate(number) is Some(whole)) {\012      if (Float.fromInt(whole) == number) {\012        return `${Int.toString(whole)}.0`\012      }\012    }\012  }\012  return Float.toString(number)\012}\012\012function writeString(mutable builder: StringBuilder, text: string) uses alloc {\012  Str.append(mutable builder, \"\\\"\")\012  const length = Str.length(text)\012  // The start of the bytes that need no escape and are not yet copied.\012  let runStart = 0\012  let index = 0\012  while (index < length) {\012    const byte = Str.byteAt(text, index)\012    if (byte >= 32 && byte != 34 && byte != 92) {\012      index += 1\012      continue\012    }\012    Str.append(mutable builder, cutText(text, runStart, index))\012    Str.append(mutable builder, escapeByte(byte))\012    index += 1\012    runStart = index\012  }\012  Str.append(mutable builder, cutText(text, runStart, length))\012  Str.append(mutable builder, \"\\\"\")\012}\012\012// The JSON escape for a quote, a backslash or a control character.\012function escapeByte(byte: int): string uses alloc {\012  if (byte == 34) {\012    return \"\\\\\\\"\"\012  }\012  if (byte == 92) {\012    return \"\\\\\\\\\"\012  }\012  if (byte == 10) {\012    return \"\\\\n\"\012  }\012  if (byte == 13) {\012    return \"\\\\r\"\012  }\012  if (byte == 9) {\012    return \"\\\\t\"\012  }\012  if (byte == 8) {\012    return \"\\\\b\"\012  }\012  if (byte == 12) {\012    return \"\\\\f\"\012  }\012  const hex = Int.toHex(byte)\012  if (Str.repeat(\"0\", 4 - Str.length(hex)) is Some(padding)) {\012    return `\\\\u${padding}${hex}`\012  }\012  return `\\\\u${hex}`\012}\012\012// encode writes any value that implements Shape as compact JSON text.\012export function encode<T: Shape>(value: T): string uses alloc {\012  return stringify(Shape.toValue(value))\012}\012\012// decode reads JSON text as a T: `Json.decode<User>(text)`. A parse error is\012// passed through; a shape error reads `<path>: <reason>` (see std/shape).\012export function decode<T: Shape>(text: string): Result<T, string> uses alloc {\012  const value = parse(text)\012  if (value is Err(message)) {\012    return Err(message)\012  }\012  return Shape.fromValue<T>(value.value)\012}\012"};
