static lstr L9070 = {-1, 2209, "// std/math: the usual number functions. The float functions are the ones of C's math.h.\012\012import * as Float from \"std/float\"\012import * as Libm from \"std/internal/math\"\012\012export const PI: f64 = 3.141592653589793\012export const E: f64 = 2.718281828459045\012\012export function abs(value: int): int {\012  if (value < 0) {\012    return 0 - value\012  }\012  return value\012}\012\012export function absFloat(value: f64): f64 {\012  if (value < 0.0) {\012    return 0.0 - value\012  }\012  return value\012}\012\012export function min<T: Ordered>(first: T, second: T): T from first {\012  return match (Ordered.compare(second, first)) { Ordering.Less => copy(second), _ => first }\012}\012\012export function max<T: Ordered>(first: T, second: T): T from first {\012  return match (Ordered.compare(second, first)) { Ordering.Greater => copy(second), _ => first }\012}\012\012export function clamp<T: Ordered>(value: T, low: T, high: T): Option<T> from value {\012  if (Ordered.compare(low, high) is Ordering.Greater) {\012    return None\012  }\012  return Some(min(max(value, low), high))\012}\012\012export function pow(base: f64, exponent: f64): f64 {\012  return Libm.pow(base, exponent)\012}\012\012export function powInt(base: int, exponent: int): Option<int> {\012  if (exponent < 0) {\012    return None\012  }\012  let result = 1\012  let factor = base\012  let remaining = exponent\012  while (remaining > 0) {\012    if (remaining % 2 == 1) {\012      result *= factor\012    }\012    remaining /= 2\012    if (remaining > 0) {\012      factor *= factor\012    }\012  }\012  return Some(result)\012}\012\012export function sqrt(value: f64): f64 {\012  return Float.sqrt(value)\012}\012\012export function floor(value: f64): f64 {\012  return Libm.floor(value)\012}\012\012export function ceil(value: f64): f64 {\012  return Libm.ceil(value)\012}\012\012export function round(value: f64): f64 {\012  return Libm.round(value)\012}\012\012export function trunc(value: f64): f64 {\012  return Libm.trunc(value)\012}\012\012export function sin(value: f64): f64 {\012  return Libm.sin(value)\012}\012\012export function cos(value: f64): f64 {\012  return Libm.cos(value)\012}\012\012export function tan(value: f64): f64 {\012  return Libm.tan(value)\012}\012\012export function atan2(y: f64, x: f64): f64 {\012  return Libm.atan2(y, x)\012}\012\012export function exp(value: f64): f64 {\012  return Libm.exp(value)\012}\012\012export function log(value: f64): f64 {\012  return Libm.log(value)\012}\012"};
static lstr L9071 = {-1, 10, "std/option"};
static lstr L9072 = {-1, 1129, "// std/option: helpers over the prelude Option.\012\012@inline\012export function map<T, U, effect E>(\012  option: Option<T>,\012  f: (value: T) => U uses E\012): Option<U> uses alloc, E {\012  return match (option) { Some(value) => Some(f(value)), None => None }\012}\012\012@inline\012export function andThen<T, U, effect E>(\012  option: Option<T>,\012  f: (value: T) => Option<U> uses E\012): Option<U> uses E {\012  return match (option) { Some(value) => f(value), None => None }\012}\012\012export function withDefault<T>(option: Option<T>, fallback: T): T from option {\012  return match (option) { Some(value) => value, None => copy(fallback) }\012}\012\012@inline\012export function orElse<T, effect E>(\012  option: Option<T>,\012  f: () => Option<T> uses E\012): Option<T> from option uses E {\012  return match (option) { Some(_) => option, None => f() }\012}\012\012export function isSome<T>(option: Option<T>): bool {\012  return option is Some(_)\012}\012\012export function isNone<T>(option: Option<T>): bool {\012  return option is None\012}\012\012export function okOr<T, F>(option: Option<T>, error: F): Result<T, F> from option uses alloc {\012  return match (option) { Some(value) => Ok(value), None => Err(copy(error)) }\012}\012"};
