  narra_free(m->keys); narra_free(m->vals); narra_free(m->hashes);
  narra_free(m->alive); narra_free(m->idx);
  m->keys = n->keys; m->vals = n->vals; m->hashes = n->hashes;
  m->alive = n->alive; m->idx = n->idx;
  m->cap = cap; m->mask = n->mask; m->used = j;
